  'settings.whatsapp.allowedHosts': 'Servidores autorizados',
  'settings.whatsapp.allowedHostsHint': 'Um por linha. Deixe vazio para permitir qualquer servidor público; endereços internos são sempre bloqueados. Use *.dominio.com para subdomínios.',
